-- Corte 9b · Fase 3 · carga del flujo del modelo · 1. los 9580 tubos. Generado por carga_flujo.py.
insert into redes.ref_cargas (conjunto, archivo, md5, filas, origen, nota, autor)
values ('flujo_modelo', 'flujo_modelo_v1.csv', '2b0b8616697e22427f7019f766de1448', 9580, 'modeloV1 del Plan Maestro 2014, corrido en EPANET (wntr): flujo por tubo. Modelo, no medido', '9580 tubos del modelo; 8669 amarran con un tramo de la red (3747 por la llave y 4922 por geometría a 2 m) y 911 no. Hora de mayor consumo 17:00 (2944 L/s) y de menor 23:00 (2722 L/s), entre las horas en que el modelo es confiable', lower(:'solicitante')) returning id as fl \gset
insert into redes.flujo_modelo_horas (carga_id, cual, hora, consumo_lps) values (:fl, 'mayor', 17, 2943.6), (:fl, 'menor', 23, 2722.1);
create temp table _fl (llave text, codigo text, amarre text, geom_mismo boolean, q1 numeric, v1 numeric, s1 text, q2 numeric, v2 numeric, s2 text) on commit drop;
